mapper.select:
SELECT a.*
FROM RE_TASK_BRANCH_ASSIGNMENT a
INNER JOIN RE_TASK_INSTANCE i ON i.ID = a.TASK_INSTANCE_ID
INNER JOIN RE_TASK t ON t.ID = i.TASK_ID
LEFT JOIN RE_PARTY_ORG p ON p.ID = a.BRANCH_ID
LEFT JOIN RE_TASK_SUBMISSION s
  ON s.ASSIGNMENT_ID = a.ID
 AND s.DELETED = 0
 AND NOT EXISTS (
     SELECT 1
     FROM RE_TASK_SUBMISSION newer
     WHERE newer.ASSIGNMENT_ID = s.ASSIGNMENT_ID
       AND newer.DELETED = 0
       AND (newer.VERSION_NO > s.VERSION_NO
            OR (newer.VERSION_NO = s.VERSION_NO AND newer.ID > s.ID))
 )
WHERE t.STATUS = 'PUBLISHED'
  AND t.DELETED = 0

  AND a.ID IN

    #{id}



  AND a.TASK_INSTANCE_ID IN

    #{id}



  AND a.BRANCH_ID IN

    #{id}



  AND a.STATUS IN

    #{status}



  AND s.STATUS IN

    #{status}



  AND t.NATURE = #{taskNature}


  AND t.TYPE_CODE = #{businessType}


  AND t.CYCLE = #{cycle}


  AND a.LAST_SUBMITTED_AT >= #{submittedStartAt}


  AND a.LAST_SUBMITTED_AT <= #{submittedEndAt}


  AND (
      t.TITLE LIKE CONCAT('%', #{keyword}, '%')
      OR t.DESCRIPTION LIKE CONCAT('%', #{keyword}, '%')
      OR p.ORG_NAME LIKE CONCAT('%', #{keyword}, '%')

        OR s.SUBMITTER_ID IN

          #{submitterId}


  )

ORDER BY a.LAST_SUBMITTED_AT DESC, a.ID DESC

SELECT a.* FROM RE_TASK_BRANCH_ASSIGNMENT a INNER JOIN RE_TASK_INSTANCE i ON i.ID = a.TASK_INSTANCE_ID INNER JOIN RE_TASK t ON t.ID = i.TASK_ID LEFT JOIN RE_PARTY_ORG p ON p.ID = a.BRANCH_ID LEFT JOIN RE_TASK_SUBMISSION s ON s.ASSIGNMENT_ID = a.ID AND s.DELETED = 0 AND NOT EXISTS ( SELECT 1 FROM RE_TASK_SUBMISSION newer WHERE newer.ASSIGNMENT_ID = s.ASSIGNMENT_ID AND newer.DELETED = 0 AND (newer.VERSION_NO > s.VERSION_NO OR (newer.VERSION_NO = s.VERSION_NO AND newer.ID > s.ID)) ) WHERE i.TASK_ID = #{taskId} AND t.STATUS = 'PUBLISHED' AND t.DELETED = 0
AND a.BRANCH_ID = #{branchId}
AND a.STATUS = #{status}
AND a.LAST_SUBMITTED_AT >= #{submittedStartAt}
AND a.LAST_SUBMITTED_AT <= #{submittedEndAt}
AND ( LOWER(COALESCE(p.ORG_NAME, '')) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(COALESCE(s.SUBMITTER_ID, '')) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(COALESCE(s.CONTENT_TEXT, '')) LIKE CONCAT('%', LOWER(#{keyword}), '%')
OR s.SUBMITTER_ID IN
#{submitterId}
)
ORDER BY a.LAST_SUBMITTED_AT DESC, a.ID DESC
